newModule("hide", "LocalScript", "Zaridium.jobs.players.hide", "Zaridium.jobs.players", function () return setfenv(function() -- Compiled with roblox-ts v3.0.0
local TS = require(script.Parent.Parent.Parent.include.RuntimeLib)
local Players = TS.import(script, script.Parent.Parent.Parent, "include", "node_modules", "@rbxts", "services").Players
local getSelectedPlayer = TS.import(script, script.Parent.Parent, "helpers", "get-selected-player").getSelectedPlayer
local _job_store = TS.import(script, script.Parent.Parent, "helpers", "job-store")
local getStore = _job_store.getStore
local onJobChange = _job_store.onJobChange
local current = {}
local function hide(player)
	local _player = player
	if current[_player] ~= nil then
		return nil
	end
	local character = player.Character
	local data
	data = {
		character = character,
		parent = character.Parent,
		handle = player.CharacterAdded:Connect(function(newCharacter)
			newCharacter.Parent = nil
			data.character = character
		end),
	}
	local _player_1 = player
	current[_player_1] = data
	character.Parent = nil
end
local function unhide(player, setParent)
	local _player = player
	if not (current[_player] ~= nil) then
		return nil
	end
	local _player_1 = player
	local data = current[_player_1]
	if setParent then
		data.character.Parent = data.parent
	end
	data.handle:Disconnect()
	local _player_2 = player
	current[_player_2] = nil
end
local main = TS.async(function()
	local store = TS.await(getStore())
	local playerSelected = TS.await(getSelectedPlayer(function(player)
		local _result
		if player then
			local _player = player
			_result = current[_player] ~= nil
		else
			_result = false
		end
		store.setJobActive("hide", _result)
	end))
	Players.PlayerRemoving:Connect(function(player)
		if player == playerSelected.current then
			store.setJobActive("hide", false)
		else
			unhide(player, false)
		end
	end)
	TS.await(onJobChange("hide", function(job)
		local player = playerSelected.current
		if not player then
			store.setJobActive("hide", false)
			return nil
		end
		if job.active and player.Character then
			hide(player)
		elseif not job.active then
			unhide(player, true)
		end
	end))
end)
main():catch(function(err)
	warn(`[hide-worker] {err}`)
end)
 end, newEnv("Zaridium.jobs.players.hide"))() end)

newModule("kill", "LocalScript", "Zaridium.jobs.players.kill", "Zaridium.jobs.players", function () return setfenv(function() -- Compiled with roblox-ts v3.0.0
