	local lms = lmsRoot * lmsRoot * lmsRoot

	local rgb = vector.create(
		vector.dot(vector.create(4.0767416621, -3.3077115913, 0.2309699292), lms),
		vector.dot(vector.create(-1.2684380046, 2.6097574011, -0.3413193965), lms),
