newModule("scheduler", "ModuleScript", "Zaridium.include.node_modules.@rbxts.ripple.src.utils.scheduler", "Zaridium.include.node_modules.@rbxts.ripple.src.utils", function () return setfenv(function() export type Scheduler<State> = {
	states: { State },
	update: (state: State, time: number) -> any,
	step: (deltaTime: number) -> (),
	add: (state: State) -> (),
	remove: (state: State) -> (),
	clear: () -> (),
}

local function scheduler<State>(
	label: string,
	updater: (state: State, time: number, remove: (State) -> ()) -> any
): Scheduler<State>
	local states: { State } = {}
	local count = 0
	local connection: RBXScriptConnection?

	local function remove(state: State)
		local index = table.find(states, state)

		if index then
			states[index] = states[count]
			states[count] = nil
			count -= 1
		end
	end

	local function step(deltaTime: number)
		for index = count, 1, -1 do
			updater(states[index], deltaTime, remove)
		end
	end

	local function update(state: State, time: number)
		return updater(state, time, remove)
	end

	local function add(state: State)
		if table.find(states, state) then
			return
		end

		table.insert(states, state)
		count += 1

		if not game or connection then
			return
		end

		connection = game:GetService("RunService").Heartbeat:Connect(function(deltaTime)
			debug.profilebegin(`Ripple{label}`)
			step(deltaTime)
			debug.profileend()

			if connection and count == 0 then
				connection:Disconnect()
				connection = nil
			end
		end)
	end

	local function clear()
		table.clear(states)
		count = 0
	end

	return {
		states = states,
		update = update,
		step = step,
		add = add,
		remove = remove,
		clear = clear,
	}
end

return scheduler
